#!/usr/bin/env bash
# Generates and configures the ios/ project (idempotent). Run from the repo root on macOS:
#
#   bash tool/ios_setup.sh
#
# The ios/ directory is generated by `flutter create` instead of being committed, then
# patched here for everything Boorusphere needs on iOS:
#   - AppDelegate: flutter_downloader plugin registrant callback
#   - Info.plist: downloads visible in the Files app, background downloads,
#     cleartext HTTP for boorus without TLS, app name
#   - Podfile / Xcode: iOS 13 deployment target (required by media_kit)
#   - app icon generated from assets/icons/exported/legacy-fill.png
set -euo pipefail

if [ "$(uname)" != "Darwin" ]; then
  echo "tool/ios_setup.sh needs macOS (PlistBuddy)." >&2
  exit 1
fi

if [ ! -f pubspec.yaml ]; then
  echo "Run this from the repository root." >&2
  exit 1
fi

ORG="io.chaldeaprjkt"
PROJECT="boorusphere"
DISPLAY_NAME="Boorusphere"

# 1. Generate the iOS runner if needed
if [ ! -d ios ]; then
  flutter create --platforms=ios --org "$ORG" --project-name "$PROJECT" .
fi

flutter pub get

# 2. App icon (non-fatal)
if [ -f assets/icons/exported/legacy-fill.png ]; then
  cat > flutter_launcher_icons-ios.yaml <<EOF
flutter_launcher_icons:
  ios: true
  android: false
  image_path: "assets/icons/exported/legacy-fill.png"
  remove_alpha_ios: true
EOF
  dart run flutter_launcher_icons -f flutter_launcher_icons-ios.yaml \
    || echo "WARNING: icon generation failed, continuing with the default icon"
  rm -f flutter_launcher_icons-ios.yaml
fi

# 3. AppDelegate (flutter_downloader needs to register its plugins for background isolates)
cat > ios/Runner/AppDelegate.swift <<'EOF'
import Flutter
import UIKit
import flutter_downloader

@main
@objc class AppDelegate: FlutterAppDelegate {
  override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
  ) -> Bool {
    GeneratedPluginRegistrant.register(with: self)
    FlutterDownloaderPlugin.setPluginRegistrantCallback(registerPlugins)
    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }
}

private func registerPlugins(registry: FlutterPluginRegistry) {
  if !registry.hasPlugin("FlutterDownloaderPlugin") {
    FlutterDownloaderPlugin.register(
      with: registry.registrar(forPlugin: "FlutterDownloaderPlugin")!)
  }
}
EOF

# 4. Info.plist
PLIST=ios/Runner/Info.plist
PB=/usr/libexec/PlistBuddy

set_or_add() { # key type value
  "$PB" -c "Set :$1 $3" "$PLIST" 2>/dev/null || "$PB" -c "Add :$1 $2 $3" "$PLIST"
}

set_or_add CFBundleDisplayName string "$DISPLAY_NAME"
# Downloads/backups live in Documents/Boorusphere and should show up in the Files app
set_or_add UIFileSharingEnabled bool true
set_or_add LSSupportsOpeningDocumentsInPlace bool true
# flutter_downloader settings
set_or_add FDMaximumConcurrentTasks integer 3
set_or_add FDAllowsCellularAccess bool true
# Some boorus are plain HTTP; AVPlayer/NSURLSession (downloads) enforce ATS
"$PB" -c "Delete :NSAppTransportSecurity" "$PLIST" 2>/dev/null || true
"$PB" -c "Add :NSAppTransportSecurity dict" "$PLIST"
"$PB" -c "Add :NSAppTransportSecurity:NSAllowsArbitraryLoads bool true" "$PLIST"
# flutter_downloader background modes
"$PB" -c "Delete :UIBackgroundModes" "$PLIST" 2>/dev/null || true
"$PB" -c "Add :UIBackgroundModes array" "$PLIST"
"$PB" -c "Add :UIBackgroundModes:0 string fetch" "$PLIST"
"$PB" -c "Add :UIBackgroundModes:1 string remote-notification" "$PLIST"

# 5. iOS 13 deployment target (media_kit requirement)
python3 - <<'EOF'
import pathlib, re
p = pathlib.Path("ios/Podfile")
s = p.read_text()
if not re.search(r"^platform :ios", s, re.M):
    s, n = re.subn(r"^#\s*platform :ios, '[0-9.]+'", "platform :ios, '13.0'", s, count=1, flags=re.M)
    if n == 0:
        s = "platform :ios, '13.0'\n" + s
else:
    s = re.sub(r"^platform :ios, '[0-9.]+'", "platform :ios, '13.0'", s, count=1, flags=re.M)
p.write_text(s)
EOF
sed -i.bak "s/IPHONEOS_DEPLOYMENT_TARGET = [0-9.]*;/IPHONEOS_DEPLOYMENT_TARGET = 13.0;/g" \
  ios/Runner.xcodeproj/project.pbxproj
rm -f ios/Runner.xcodeproj/project.pbxproj.bak

echo "iOS project ready."
